Section FIX.
  Context {HCEIL : HeapCeil}.
  Variables (ra sp gp tp t0 t1 t2 s0 s1 a0 a1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6 : word)
            (F : bvmap 5 word) (fc : bv 32) (m : word -> option byte) (lo c : Z) (e0 : word).
  Notation nptr := (bv_unsigned a1).
  Notation endp := (bv_unsigned a2).
  Notation nn := (c + 1).
  Hypothesis Ha3 : a3 = Z_to_bv 64 (nptr + c).
  Hypothesis Ha4 : a4 = Z_to_bv 64 0.
  Hypothesis HC : 1 <= c <= 63.
  Hypothesis EW : rw_cells bsegs m endp [C8 e0].
  Hypothesis ETOP : AIMG_TOP <= endp.
  Hypothesis ACCE : accessible m endp 8.
  Hypothesis SVE : shvis m endp (endp + 8).
  Hypothesis INME : in_app_mem endp (endp + 8).
  Hypothesis ACCS : accessible m nptr nn.
  Hypothesis SVS : shvis m nptr (nptr + nn).
  Hypothesis INMS : in_app_mem nptr (nptr + nn).
  Hypothesis ST0 : stk bsegs m lo (bv_unsigned sp).
  Hypothesis CEIL : aceil <= lo.
  Hypothesis LO : lo <= bv_unsigned sp - 2224.   (* [comment removed for export] *)
  Hypothesis MI : mem_inv bsegs m.
  Hypothesis AC : ACONST m.
  Hypothesis DJE : endp + 8 <= lo \/ bv_unsigned sp <= endp.

  Definition sfx_post : machine_state -> Prop :=
    fun ms' => exists x5 x6 x7 x10 x11 x12 x13 x14 x15 x16 x17 x28 x29 x30 x31 m',
      ms' = MS (mkR ra sp gp tp x5 x6 x7 s0 s1 x10 x11 x12 x13 x14 x15 x16 x17 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 x28 x29 x30 x31)
               F (ret_pc ra) fc None m' (seg_rom bsegs)
      /\ munch [(bv_unsigned sp - 2224, bv_unsigned sp); (endp, endp + 8)]%Z m m' /\ wmono bsegs m m' /\ mem_inv bsegs m'
      /\ stk bsegs m' lo (bv_unsigned sp)
      /\ rw_cells bsegs m' endp [C8 (Z_to_bv 64 (nptr + c))]
      /\ ACONST m'.
  Notation POST := sfx_post.
  Notation SP2 := (Z_to_bv 64 (bv_unsigned sp + -2144)).
  Notation W := [(bv_unsigned sp - 2224, bv_unsigned sp); (endp, endp + 8)].
  (* [comment removed for export] *)
  Notation RST pc x1 x5 x6 x7 x10 x11 x12 x13 x14 x15 x16 x17 x19 x20 x22 x23 x28 x29 x30 x31 mm :=
    (MS (mkR x1 SP2 gp tp x5 x6 x7 sp a0 x10 x11 x12 x13 x14 x15 x16 x17 a1 x19 x20 SP2 x22 x23 s8 s9 s10 s11 x28 x29 x30 x31)
